import Foundation

// LogMonitorAgent - processes uploaded log files from users
// Runs as a privileged daemon for system-wide log aggregation

struct LogEntry: Codable {
    let timestamp: String
    let level: String
    let message: String
    let metadata: [String: String]?
}

struct UploadManifest: Codable {
    let version: Int
    let entries: [LogEntry]
    let processingHints: ProcessingHints?
}

struct ProcessingHints: Codable {
    let outputFormat: String?
    let filterPattern: String?
    let postProcessCommand: String?
    let archivePath: String?
}

class SandboxPolicy {
    private let allowedCommands: Set<String> = ["gzip", "bzip2", "xz"]
    private let allowedPaths: [String] = ["/var/log/agent/", "/tmp/agent/"]

    func isCommandAllowed(_ command: String) -> Bool {
        let binary = URL(fileURLWithPath: command).lastPathComponent
        return allowedCommands.contains(binary)
    }

    func isPathAllowed(_ path: String) -> Bool {
        let resolved = resolvePath(path)
        return allowedPaths.contains(where: { resolved.hasPrefix($0) })
    }

    private func resolvePath(_ path: String) -> String {
        // Use FileManager for canonical path resolution including symlinks
        let url = URL(fileURLWithPath: path).standardized
        let canonical = (try? FileManager.default.destinationOfSymbolicLink(atPath: url.path)) ?? url.path
        let finalURL = URL(fileURLWithPath: canonical).standardized
        return finalURL.path + (finalURL.path.hasSuffix("/") ? "" : "/")
    }
}

class CommandExecutor {
    private let policy: SandboxPolicy

    init(policy: SandboxPolicy) {
        self.policy = policy
    }

    func executeArchival(command: String, inputPath: String, outputPath: String) -> Bool {
        guard policy.isCommandAllowed(command) else {
            print("[SECURITY] Command not in allowlist: \(command)")
            return false
        }
        guard policy.isPathAllowed(outputPath) else {
            print("[SECURITY] Output path not allowed: \(outputPath)")
            return false
        }

        // Resolve to absolute path and verify it's actually an allowed binary
        let resolvedBinary = "/usr/bin/" + command
        guard FileManager.default.isExecutableFile(atPath: resolvedBinary) else {
            print("[SECURITY] Binary not found at expected path: \(resolvedBinary)")
            return false
        }

        let process = Process()
        process.executableURL = URL(fileURLWithPath: resolvedBinary)
        process.arguments = ["-c"]
        process.currentDirectoryURL = URL(fileURLWithPath: "/tmp/agent/")

        // Set input from file
        if let inputHandle = FileHandle(forReadingAtPath: inputPath) {
            process.standardInput = inputHandle
        } else {
            return false
        }

        // Set output redirection
        let outputFile = FileHandle(forWritingAtPath: outputPath)
        if let handle = outputFile {
            process.standardOutput = handle
        } else {
            return false
        }

        do {
            try process.run()
            process.waitUntilExit()
            return process.terminationStatus == 0
        } catch {
            print("[ERROR] Process execution failed: \(error)")
            return false
        }
    }
}

class LogProcessingPipeline {
    private let executor: CommandExecutor
    private let workDir = "/tmp/agent/processing/"
    // Bound the maximum length of text evaluated against a user-supplied regex
    // to mitigate pathological backtracking (ReDoS).
    private let maxRegexSearchLength = 8192

    init(executor: CommandExecutor) {
        self.executor = executor
    }

    func processUpload(data: Data) -> Bool {
        let decoder = JSONDecoder()
        guard let manifest = try? decoder.decode(UploadManifest.self, from: data) else {
            print("[ERROR] Failed to decode upload manifest")
            return false
        }

        // Process log entries
        let processed = processEntries(manifest.entries, hints: manifest.processingHints)

        // Handle archival if requested
        if let hints = manifest.processingHints,
           let archivePath = hints.archivePath {
            let tempFile = workDir + UUID().uuidString + ".log"
            writeProcessedLogs(processed, to: tempFile)

            let compressor = resolveCompressor(hints.outputFormat)
            return executor.executeArchival(
                command: compressor,
                inputPath: tempFile,
                outputPath: archivePath
            )
        }

        return true
    }

    private func resolveCompressor(_ format: String?) -> String {
        switch format?.lowercased() {
        case "gz", "gzip": return "gzip"
        case "bz2", "bzip2": return "bzip2"
        case "xz": return "xz"
        default: return "gzip"
        }
    }

    private func processEntries(_ entries: [LogEntry], hints: ProcessingHints?) -> [String] {
        var results: [String] = []

        // Pre-compile the user-supplied filter pattern once, with validation.
        // Passing an unvalidated user string directly to the regex engine on every
        // line risks catastrophic backtracking / ReDoS in this privileged daemon.
        var filterRegex: NSRegularExpression? = nil
        if let filter = hints?.filterPattern {
            // Reject overly long patterns outright.
            guard filter.utf16.count <= 1024 else {
                print("[SECURITY] Filter pattern rejected: too long")
                return results
            }
            do {
                filterRegex = try NSRegularExpression(pattern: filter, options: [])
            } catch {
                print("[SECURITY] Invalid filter pattern rejected: \(error)")
                return results
            }
        }

        for entry in entries {
            var line = "[\(entry.timestamp)] [\(entry.level)] \(entry.message)"
            if let regex = filterRegex {
                // Bound the searched range to limit worst-case matching cost.
                let ns = line as NSString
                let searchLength = min(ns.length, maxRegexSearchLength)
                let range = NSRange(location: 0, length: searchLength)
                if regex.firstMatch(in: line, options: [], range: range) == nil {
                    continue
                }
            }
            if let meta = entry.metadata {
                let metaStr = meta.map { "\($0.key)=\($0.value)" }.joined(separator: "; ")
                line += " {\(metaStr)}"
            }
            results.append(line)
        }
        return results
    }

    private func writeProcessedLogs(_ lines: [String], to path: String) {
        let content = lines.joined(separator: "\n")
        try? content.write(toFile: path, atomically: true, encoding: .utf8)
    }
}

// Entry point - receives upload from HTTP handler
func handleUpload(requestBody: Data) {
    let policy = SandboxPolicy()
    let executor = CommandExecutor(policy: policy)
    let pipeline = LogProcessingPipeline(executor: executor)
    let _ = pipeline.processUpload(data: requestBody)
}
